// Turns the collector's answer into one execution-log row. outcome: ok | skipped | warning | failed.
const r = $input.first().json;
const body = r.body || {};
const result = body.result || {};
const at = result.airtable || {};
const failedFeeds = ((result.feeds || {}).failed || []).map((f) => `${f.source} (${f.error})`);
const workingFeeds = ((result.feeds || {}).working || []).length;
let outcome = 'ok';
let message = 'Collection finished.';
if (r.statusCode === undefined) { outcome = 'failed'; message = `Collector unreachable: ${(r.error && (r.error.message || r.error)) || 'no response'}. Is Docker Desktop running and the aow container up?`; }
else if (r.statusCode === 409 || result.status === 'skipped') { outcome = 'skipped'; message = 'Another collection run was already in progress, so this one did nothing.'; }
else if (r.statusCode === 401) { outcome = 'failed'; message = 'Trigger token rejected: the n8n credential "AOW Trigger Token" does not match AOW_TRIGGER_TOKEN.'; }
else if (r.statusCode !== 200) { outcome = 'failed'; message = `Collector answered HTTP ${r.statusCode}: ${body.error || 'unknown error'}`; }
else if (!result.ok) { outcome = 'failed'; message = `Collection failed: ${result.error || 'unknown error'}`; }
else if (at.error || at.reconciled === false) { outcome = 'failed'; message = `Airtable sync failed; articles stay queued locally and retry next run: ${at.error || 'reconcile failed'}`; }
else if (workingFeeds === 0) { outcome = 'failed'; message = 'No RSS feed could be read (network problem?).'; }
else if (at.skipped === 'monthly_call_budget_reached') { outcome = 'warning'; message = 'Airtable monthly call budget reached: articles are kept locally and sync resumes next month.'; }
else if (at.usage_warning) { outcome = 'warning'; message = at.usage_warning; }
else if (failedFeeds.length > 3) { outcome = 'warning'; message = `${failedFeeds.length} feeds failed: ${failedFeeds.join(', ')}`; }
return [{ json: {
  outcome,
  message,
  run_id: result.run_id || body.run_id || null,
  new_articles: result.new_articles ?? null,
  already_stored: result.already_stored ?? null,
  new_editorial_candidates: result.new_editorial_candidates ?? null,
  synced_to_airtable: at.synced ?? null,
  left_for_next_run: at.left_for_next_run ?? null,
  records_used_estimate: at.records_used_estimate ?? null,
  airtable_calls_this_month: at.calls_this_month ?? null,
  failed_feeds: failedFeeds,
  paid_api_calls: result.network ? result.network.paid_api_calls : 0,
} }];
